use std::{fs,path::Path,collections::BTreeMap,fmt::Write};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-arithmetic-leaves";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-27-arithmetic-leaves";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){let r=Path::new(R);let d=Path::new(D);let a=read(r.join("analysis.json"));assert_eq!(a["SDK_requests"],652);assert_eq!(a["next_prior_count"],7205);let pins=read(r.join("capture-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new("/home/ubuntu/src/zk-tools/zopro").join(p)),h.as_str().unwrap());}assert_eq!(read(r.join("native/core/tests.json"))["passed_tests"].as_array().unwrap().len(),111);let inventory=read(r.join("proof-inventory.json"));assert_eq!(inventory.as_object().unwrap().len(),56);for(p,h)in inventory.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}for(p,h)in read(r.join("raw-local-sha256.json")).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let audit=json!({"status":"bounded arithmetic-leaf trace experiment complete","low_overhead_qualified":a["low_overhead_qualified"],"complete_enabled_graphs":a["complete_enabled_graphs"],"incomplete_enabled_graphs":a["incomplete_enabled_graphs"],"SDK_requests":652,"independent_gnark_exports":28,"proof_public_members":56,"next_prior_count":7205,"native_core_tests":111,"new_recorder_tests":2,"raw_tests":2,"cubic_tests":6,"field_source_qualification_inherited":true,"production_sources_checked_unchanged":170,"closing_pins_checked":pins.as_object().unwrap().len(),"new_arithmetic_or_schedule":false,"adopted":false,"goal_achieved":false,"next_action":"Use only validated complete instrumented graphs to choose a substantive arithmetic/dataflow hypothesis. Respect calibration/observer-overhead failures; never replace accepted timings or extrapolate serial CPU as removable wall time. Preserve earlier positive candidates and full all-eight10x objective; no unchanged recorder/null/pool/wait reroll."});save(r.join("closeout.json"),&audit);
 let mut md=format!("# MSM arithmetic leaves and input availability\n\nThe recorder produced **{} complete enabled graphs** and **{} incomplete graphs**. Its declared low-overhead check passes: **{}**. These are measurements of instrumented execution; no proving optimization is adopted and accepted latency remains unchanged.\n\nThe diagnostic records elapsed spans at whole queries, kernel input availability, windows and parts. Serial scopes also record thread CPU at fills, streaming batches, inversions and reduction tiles. Explicit IDs cross nested Rayon closures, including top-window joins. Whole-query boundaries keep grouping from inheriting a waiting sibling's context. Serial CPU includes system and recorder work; it is not a field-instruction count. Nested serial CPU is subtracted to avoid double counting. Window callbacks remain wall-only because they can help other jobs while waiting.\n\nA/KH input availability is their kernel entry. G2 window inputs become available after scalar decomposition joins. These markers are not enqueue timestamps: Rayon creates jobs lazily. Uncovered preprocessing, scattering, folding, assembly and verification remain outside the recorded serial service.\n\n## Overhead and calibration\n\nPrimary1x2, Ryzen9950X,16workers/CPUs0–15 and32workers/CPUs0–31. Three rotated/reversed fresh-process blocks compare the exact accepted SDK with recorder OFF/ON in one new linked SDK. Each process has31timed requests after3primes. Both recorder modes reset/snapshot outside each request timer. The custom driver and outside-timer work can change context; OFF/accepted checks assess that difference.\n\n|Workers|Accepted ms|OFF ms|ON ms|ON/OFF paired|ON CPU ms/request|ON lifetime RSS MiB|\n|---|---:|---:|---:|---:|---:|---:|\n",a["complete_enabled_graphs"],a["incomplete_enabled_graphs"],a["low_overhead_qualified"]);
 for workers in ["16","32"]{let c=&a["cases"][workers];writeln!(md,"|{workers}|{:.6}|{:.6}|{:.6}|{:.6}|{:.3}|{:.2}|",c["modes"]["accepted"]["ms"].as_f64().unwrap(),c["modes"]["off"]["ms"].as_f64().unwrap(),c["modes"]["on"]["ms"].as_f64().unwrap(),c["ON_OFF_geometric"].as_f64().unwrap(),c["modes"]["on"]["CPU_ms_per_request"].as_f64().unwrap(),c["modes"]["on"]["max_lifetime_RSS_mib"].as_f64().unwrap()).unwrap();}
 writeln!(md,"\nCalibration failures: `{}`.\n\nObserver-overhead failures: `{}`.\n",a["calibration_failures"],a["overhead_failures"]).unwrap();md.push_str("Calibration uses factor1.05 per OFF/accepted block and factor1.03 for its paired median. ON/OFF geometric overhead must be at most10% at both counts. Failure means low-overhead qualification does not hold; trace results remain descriptions of the instrumented schedule. No reruns, exclusions or threshold changes occur. Small optimization gains retain no minimum adoption floor; this diagnostic is not an optimization.\n\n## Covered serial work\n\nMedians below use only complete fixed-position graphs (requests0,15,30 in each ON process). Each request contributes its own query/window boundaries and recorded serial CPU. Last-query counts identify which recorded query finishes last under instrumentation, not a removable critical-path duration.\n\n|Workers|Query|Complete graphs|Last-query count|Query elapsed ms|Covered serial CPU ms|Covered inverse CPU ms|Pre-kernel elapsed ms|Median available-to-window-start ms|Maximum available-to-start ms|\n|---|---|---:|---:|---:|---:|---:|---:|---:|---:|\n");for workers in ["16","32"]{let t=&a["trace_aggregates"][workers];for name in ["a","kh","g2"]{let q=&t["queries"][name];if q.is_null(){continue;}writeln!(md,"|{workers}|{name}|{}|{}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|{:.6}|",t["complete_graphs"],t["last_query_counts"][name].as_u64().unwrap_or(0),q["median_query_elapsed_ms"].as_f64().unwrap(),q["median_covered_serial_CPU_ms"].as_f64().unwrap(),q["median_covered_inverse_CPU_ms"].as_f64().unwrap(),q["median_pre_kernel_elapsed_ms"].as_f64().unwrap(),q["median_window_input_available_to_start_ms"].as_f64().unwrap(),q["max_window_input_available_to_start_ms"].as_f64().unwrap()).unwrap();}}
 md.push_str("\nSummed serial CPU can exceed elapsed time because workers run concurrently. It includes bookkeeping, memory access, allocation already in the original arithmetic bodies, and observer cost. Available-to-start includes all work between mathematical availability and callback execution and does not isolate executor dispatch. Neither sum is a predicted proof speedup. Full per-window values and exclusive CPU categories are in [graphs](artifacts/graphs.json); all request timings, resources and event/drop counts are in [rows](artifacts/rows.json). Incomplete graphs remain reported and their timings are retained; they do not support complete-graph attribution.\n\n## Validation, memory and provenance\n\nAll111native core tests, raw2/cubic6, generator and portable/no-IFMA consumers pass. Two recorder tests cover explicit parent boundaries, serial CPU clocks, disabled/unwind behavior, and bounded capacity/drop reporting. Existing field qualification is inherited unchanged. A first native build completed before capture; source review then added whole-query boundaries to fix grouping attribution before a fresh validated build. The superseded pre-capture version is retained with [correction notes](artifacts/pre-capture-correction.md); it produced no measurements.\n\nSix original files contain only recorded diagnostic insertions/wrappers; reversing them recovers every original byte. The other164originals and all170production files remain unchanged. One new cfg-only module records metadata. No arithmetic, scheduling, field primitive, table, second plan or pool is added.\n\nThe recorder allocates8192events of80bytes per worker/caller before primes and retains capacity between requests. At32workers this is at most20.625MiB plus Vec metadata. Snapshots outside request timing copy recorded events; only fixed early/middle/late graphs are retained. There is no universal product RAM cap or default tracing allocation. Peak RSS includes key load, primes, recorder and snapshots and is not minimum RAM. Overflow preserves proof execution and reports dropped counts; no buffer is increased to obtain a complete graph. Raw event files remain local and hashed; gzip copies are archived after all captures. The decoder checks record sizes, IDs, parents, containment, worker identities and serial CPU nesting.\n\nAll-nine OFF plus primary ON four-worker preflight contributes40SDK requests/10exports. The primary matrix contributes612SDK/18exports. Total **652 SDK requests**, **28 fresh independently verified Gnark exports**, **56 proof/public members**; the next ledger count is **7,205**. Every export passes164-byte length, pinned public binding, freshness against7,177prior identities and independent verification. No helper, build, hash, archive or verifier overlaps timed captures.\n\nThe [last complete SDK matrix](../2026-10-26-pairing-x-chain-sdk/README.md) retains all supplied M5CPU/Metal comparisons. No new all-shape performance qualification, AWS/Aeglos, phone, TEE, giant-circuit, swap, minimum-RAM, pressure, concurrency or throughput qualification is claimed. The all-eightCPU10× objective remains active and unmet. The earlier37µs fusion signal and failed qualification remain unchanged.\n\n");let b=read(r.join("native/trace/artifacts.json"));writeln!(md,"Executable: `{}`; SHA-256 `{}`.\n",b["binary"].as_str().unwrap(),b["binary_sha256"].as_str().unwrap()).unwrap();md.push_str("[Design](artifacts/design.md), [serial-scope audit](artifacts/serial-scopes.md), [source audit](artifacts/source-audit.json), [native tests](artifacts/native/core/tests.json), [proof inventory](artifacts/proof-inventory.json), [raw local hashes](artifacts/raw-local-sha256.json), [artifact hashes](artifact-index.json).\n");fs::create_dir_all(d).unwrap();fs::write(d.join("README.md"),md).unwrap();fs::copy("/tmp/zopro-grouping-module/production-source-manifest.json",r.join("accepted-source-manifest.json")).unwrap();let mut index=BTreeMap::new();archive(r,r,&d.join("artifacts"),&mut index);for(rel,h)in &index{assert_eq!(&hash(d.join("artifacts").join(rel)),h);}for(p,h)in inventory.as_object().unwrap(){let rel=Path::new(p).strip_prefix(r).unwrap();assert_eq!(hash(d.join("artifacts").join(rel)),h.as_str().unwrap());}save(d.join("artifact-index.json"),&json!(index));println!("{}artifact hashes/56proofmembers checked;652SDK28Gnark;prior7205",index.len());}
fn archive(root:&Path,here:&Path,dest:&Path,index:&mut BTreeMap<String,String>){let mut paths:Vec<_>=fs::read_dir(here).unwrap().map(|e|e.unwrap().path()).collect();paths.sort();for p in paths{let rel=p.strip_prefix(root).unwrap();let s=rel.display().to_string();if s.starts_with("target-"){continue;}if p.is_dir(){archive(root,&p,dest,index);continue;}if s.starts_with("candidate/")&&!["candidate/crates/zopro-core/src/lib.rs","candidate/crates/zopro-core/src/msm.rs","candidate/crates/zopro-core/src/msm_affine.rs","candidate/crates/zopro-core/src/msm/g2_prefix.rs","candidate/crates/zopro-core/src/msm_affine/fused_kh.rs","candidate/crates/zopro-core/src/msm_affine/g2_phi.rs","candidate/crates/zopro-core/src/arithmetic_trace.rs"].contains(&s.as_str()){continue;}if !["json","jsonl","rs","md","txt","log","proof","public","gz"].iter().any(|x|p.extension().is_some_and(|e|e==*x)){continue;}let q=dest.join(rel);fs::create_dir_all(q.parent().unwrap()).unwrap();fs::copy(&p,&q).unwrap();let h=hash(&q);assert_eq!(h,hash(&p));index.insert(s,h);}}
